using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using SchoolERP.Api.Security;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Features.Houses;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Security;using SchoolERP.Shared.Models;namespace SchoolERP.Api.Controllers.v1;
/// <summary>Manages persistent school Houses. ColorHex must use #RRGGBB; codes are unique per school.</summary>
[ApiController,Authorize,Route("api/v1/houses")]public sealed class HousesController(IHouseService service):ControllerBase{[HttpGet,RequirePermission(PermissionCatalog.House.View)]public async Task<ActionResult<ApiResponse<PagedResult<HouseListItemDto>>>>List([FromQuery]int pageNumber=1,[FromQuery]int pageSize=20,[FromQuery]HouseStatus? status=null,[FromQuery]string? search=null,[FromQuery]string? sortBy=null,[FromQuery]string? sortDirection=null,CancellationToken ct=default)=>Ok(ApiResponse<PagedResult<HouseListItemDto>>.Ok(await service.ListAsync(new(pageNumber,pageSize,status,search,sortBy,sortDirection),ct)));[HttpGet("{id:guid}"),RequirePermission(PermissionCatalog.House.View)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Get(Guid id,CancellationToken ct)=>R(await service.GetAsync(id,ct));[HttpPost,RequirePermission(PermissionCatalog.House.Create)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Create(CreateHouseRequest r,CancellationToken ct){var x=await service.CreateAsync(r,ct);return CreatedAtAction(nameof(Get),new{id=x.Id},ApiResponse<HouseDetailsDto>.Ok(x));}[HttpPut("{id:guid}"),RequirePermission(PermissionCatalog.House.Edit)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Update(Guid id,UpdateHouseRequest r,CancellationToken ct)=>R(await service.UpdateAsync(id,r,ct));[HttpPost("{id:guid}/change-code"),RequirePermission(PermissionCatalog.House.Edit)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Code(Guid id,ChangeHouseCodeRequest r,CancellationToken ct)=>R(await service.ChangeCodeAsync(id,r,ct));[HttpPost("{id:guid}/activate"),RequirePermission(PermissionCatalog.House.Activate)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Activate(Guid id,CancellationToken ct)=>R(await service.ActivateAsync(id,ct));[HttpPost("{id:guid}/deactivate"),RequirePermission(PermissionCatalog.House.Deactivate)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Deactivate(Guid id,CancellationToken ct)=>R(await service.DeactivateAsync(id,ct));[HttpPost("{id:guid}/archive"),RequirePermission(PermissionCatalog.House.Archive)]public async Task<ActionResult<ApiResponse<HouseDetailsDto>>>Archive(Guid id,CancellationToken ct)=>R(await service.ArchiveAsync(id,ct));private ActionResult<ApiResponse<HouseDetailsDto>>R(HouseDetailsDto?x)=>x is null?NotFound():Ok(ApiResponse<HouseDetailsDto>.Ok(x));}
